//Data Mapping
public float[] mappedFlArr(float[] flArr) { //Map wav values to fit the ui screen
  float[] temp = new float[flArr.length];
  for (int i = 0; i < flArr.length; i++) {
    temp[i] = map(flArr[i], -1, 1, 40, 320);
  }
  return temp;
}

public float[] mapEnv(float[] env) { //Map envelope values to fit the ui screen
  float totalTime = env[0]+env[1]+env[2];
  float attackTime = map(env[0], 0.0f, totalTime, 0, 640);
  float sustainTime = map(env[1], 0.0f, totalTime, 0, 640);
  float releaseTime = map(env[2], 0.0f, totalTime, 0, 640);
  return new float[]{attackTime, sustainTime, releaseTime};
}

