//Wav Generation Functions
public void defaultSin() {
  defaultWav = resetSin;
}

public void defaultSqr() {
  float[] sqrwav = new float[640];

  for (int i = 0; i < 640; i++) {
    if (i < 320) {
      sqrwav[i] = -1;
    } else {
      sqrwav[i] = 1;
    }
  }
  defaultWav=sqrwav;
}

public void defaultTri() {
  float[] triwav = new float[640];
  int counter = 0;
  for (int i = 0; i < 640; i++) {
    if (i == 0) {
      counter = 0;
    } else if (i < 160) {
      counter +=1;
    } else if (i < 480) {
      counter -=1;
      triwav[i] = counter;
    } else {
      counter +=1;
    }
    triwav[i] = map(counter, -159, 159, 1, -1);
  }
  defaultWav=triwav;
}

public void defaultSaw() {
  float[] sawwav = new float[640];
  int counter = 320;
  for (int i = 0; i < 640; i++) {
    counter -=1;
    sawwav[i] = map(counter, -319, 319, 1, -1);
  }
  defaultWav = sawwav;
}

public void defaultRamp() {
  float[] rampwav = new float[640];
  int counter = -320;
  for (int i = 0; i < 640; i++) {
    counter +=1;
    rampwav[i] = map(counter, -319, 319, 1, -1);
  }
  defaultWav=rampwav;
}

public void defaultStep() {
  float[] stepwav = new float[640];
  int counter = 0;
  int step = 0;
  for (int i = 0; i < 640; i++) {
    if (step != 16) {
      step++;
    } else {
      counter++;
      step=0;
    }
    stepwav[i] = map(counter, 0, 39, 1, -1);
  }
  defaultWav=stepwav;
}

// Envelope Editor
public void openEnvMenu() {
  if (envOpen == false) {
    createEnvGUI();
  }
}

public void closingEnv() {
  susMode = false;
  sliderMode = false;
  clearEnv = true;
  envOpen=false;
}

public void deviceControlEnv(GEvent event) {
  if (event == GEvent.DESELECTED) {
    hideAllEnv.setVisible(false);
    option1.setSelected(true);
    sustain.setVisible(true);
    sliderRatios.setVisible(true);
  } else if (event == GEvent.SELECTED) {
    sustain.setVisible(false);
    sliderRatios.setVisible(false);
    hideAllEnv.setVisible(true);
    option1.setSelected(true);
    hideSlidersEnv.setVisible(true);
    custom_slider1.setLimits(5, 0, 10);
    custom_slider2.setLimits(5, 0, 10);
    custom_slider3.setLimits(5, 0, 10);
    susMode = false;
    sliderMode = false;
    clearEnv = true;
  }
}

public void sustainMode(GEvent event) {
  if (event == GEvent.SELECTED) {
    hideSlidersEnv.setVisible(true);
    custom_slider1.setLimits(5, 0, 10);
    custom_slider2.setLimits(5, 0, 10);
    custom_slider3.setLimits(5, 0, 10);
    susMode = true;
    clearEnv = false;
    sliderMode = false;
  }
}

public void sliderModeEnv(GEvent event) {
  if (event == GEvent.SELECTED) {
    hideSlidersEnv.setVisible(false);
    custom_slider1.setLimits(5, 0, 10);
    custom_slider2.setLimits(5, 0, 10);
    custom_slider3.setLimits(5, 0, 10);
    sliderVals = new int[]{5, 5, 5};
    susMode = false;
    clearEnv = false;
    sliderMode = true;
  }
}

public void envModeReset(GEvent event) {
  if (event == GEvent.SELECTED) {
    hideSlidersEnv.setVisible(true);
    custom_slider1.setLimits(5, 0, 10);
    custom_slider2.setLimits(5, 0, 10);
    custom_slider3.setLimits(5, 0, 10);
    susMode = false;
    sliderMode = false;
    clearEnv = true;
  }
}

public void sliderUpdate(GCustomSlider source, GEvent event, int index) {
  if (event == GEvent.RELEASED) {
    sliderVals[index] = source.getValueI();
  }
}

//Help Menu
public void openHelpMenu() {
  if (helpOpen == false) {
    createHelpGUI();
  }
}

//Main Window
public void setModeKnob(GKnob source) {
  mode = source.getValueF();
}

public void setVolKnob(GKnob source) {
  volume = Math.round(source.getValueI()) * 0.1f;//Round volume
  s.volume(volume);
}


